create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique not null,bio text default '',avatar_url text,created_at timestamptz default now());
create table if not exists public.posts(id bigint generated by default as identity primary key,user_id uuid not null references public.profiles(id) on delete cascade,content text default '',image_url text,created_at timestamptz default now());
create table if not exists public.follows(follower_id uuid references auth.users(id) on delete cascade,following_id uuid references auth.users(id) on delete cascade,created_at timestamptz default now(),primary key(follower_id,following_id));
create table if not exists public.likes(user_id uuid references auth.users(id) on delete cascade,post_id bigint references public.posts(id) on delete cascade,primary key(user_id,post_id));
create table if not exists public.comments(id bigint generated by default as identity primary key,user_id uuid references auth.users(id) on delete cascade,post_id bigint references public.posts(id) on delete cascade,body text not null,created_at timestamptz default now());
create table if not exists public.messages(id bigint generated by default as identity primary key,sender_id uuid references auth.users(id) on delete cascade,receiver_id uuid references auth.users(id) on delete cascade,body text not null,created_at timestamptz default now());
alter table public.profiles enable row level security;alter table public.posts enable row level security;alter table public.follows enable row level security;alter table public.likes enable row level security;alter table public.comments enable row level security;alter table public.messages enable row level security;
create policy "profiles read" on public.profiles for select using(true);create policy "profile own insert" on public.profiles for insert with check(auth.uid()=id);create policy "profile own update" on public.profiles for update using(auth.uid()=id);
create policy "posts read" on public.posts for select using(true);create policy "posts own insert" on public.posts for insert with check(auth.uid()=user_id);create policy "posts own update" on public.posts for update using(auth.uid()=user_id);create policy "posts own delete" on public.posts for delete using(auth.uid()=user_id);
create policy "follows read" on public.follows for select using(true);create policy "follow insert" on public.follows for insert with check(auth.uid()=follower_id);create policy "follow delete" on public.follows for delete using(auth.uid()=follower_id);
create policy "likes read" on public.likes for select using(true);create policy "likes insert" on public.likes for insert with check(auth.uid()=user_id);create policy "likes delete" on public.likes for delete using(auth.uid()=user_id);
create policy "comments read" on public.comments for select using(true);create policy "comments insert" on public.comments for insert with check(auth.uid()=user_id);create policy "comments delete" on public.comments for delete using(auth.uid()=user_id);
create policy "messages participants read" on public.messages for select using(auth.uid()=sender_id or auth.uid()=receiver_id);create policy "messages sender insert" on public.messages for insert with check(auth.uid()=sender_id);